$ErrorActionPreference='Stop'; $root=$PSScriptRoot
function Median([double[]]$v){$a=@($v|Sort-Object);return $a[[int][math]::Floor($a.Count/2)]}
$all=@();$life=@()
foreach($kind in @('baseline','final')){foreach($run in 1..5){$perLife=@();foreach($line in Get-Content "$root\results\acceptance-$kind-$run.csv"){$v=$line.Split(',');if($v[0] -eq 'summary'){$all += [pscustomobject]@{kind=$kind;run=$run;key=($v[1..3]-join '/');custom=[double]$v[5];ppl=[double]$v[6];ratio=[double]$v[7];spread=[double]$v[8];pplSpread=[double]$v[9]}}elseif($v[0] -eq 'lifecycle'){$perLife += [pscustomobject]@{mode=$v[1];key=($v[2..4]-join '/');transfer=[double]$v[5];teardown=[double]$v[6];total=[double]$v[7]}}};foreach($g in ($perLife|Group-Object key)){$cu=@($g.Group|Where-Object mode -eq custom|Select-Object -Skip 2);$pl=@($g.Group|Where-Object mode -eq ppl|Select-Object -Skip 2);if($cu.Count -ne 15 -or $pl.Count -ne 15){throw 'Incorrect lifecycle count'};$life += [pscustomobject]@{kind=$kind;run=$run;key=$g.Name;ratio=(Median $cu.total)/(Median $pl.total);teardown=(Median $cu.teardown)}}}}
$summary=@();foreach($key in @('8/1/1','128/1/1','8/4/1','128/4/1','8/4/4','128/4/4')){$a=@($all|Where-Object{$_.kind -eq 'final' -and $_.key -eq $key});$b=@($all|Where-Object{$_.kind -eq 'baseline' -and $_.key -eq $key});$l=@($life|Where-Object{$_.kind -eq 'final' -and $_.key -eq $key});if($a.Count -ne 5 -or $b.Count -ne 5){throw 'Incorrect process count'};$summary += [pscustomobject]@{key=$key;before_ns=(Median $b.custom);after_ns=(Median $a.custom);ppl_ns=(Median $a.ppl);before_ratio=(Median $b.ratio);ratio=(Median $a.ratio);min_ratio=($a.ratio|Measure-Object -Minimum).Minimum;max_ratio=($a.ratio|Measure-Object -Maximum).Maximum;lifecycle_ratio=(Median $l.ratio);lifecycle_max=($l.ratio|Measure-Object -Maximum).Maximum;teardown_ns=(Median $l.teardown)}}
$summary|ConvertTo-Json -Depth 5|Set-Content -Encoding utf8 "$root\results\optimization-summary.json"
$gate=if(@($summary|Where-Object{$_.max_ratio -gt 1.10 -or $_.lifecycle_max -gt 1.10}).Count -eq 0){'PASS'}else{'FAIL'}
$table=@('| 값 / 생산자·소비자 | 이전 ns/원소 | 최종 ns/원소 | PPL ns/원소 | 최종/PPL | 5회 범위 | 소멸 포함 비율 / 최대 |','|---|---:|---:|---:|---:|---|---|')
foreach($r in $summary){$table += '| '+$r.key+' | '+$r.before_ns.ToString('F2')+' | '+$r.after_ns.ToString('F2')+' | '+$r.ppl_ns.ToString('F2')+' | '+$r.ratio.ToString('F3')+' | '+$r.min_ratio.ToString('F3')+'~'+$r.max_ratio.ToString('F3')+' | '+$r.lifecycle_ratio.ToString('F3')+' / '+$r.lifecycle_max.ToString('F3')+' |'}
function Profile([string]$file){$p=@{events=@{};objects=@{};sizes=@{}};foreach($line in Get-Content $file){$v=$line.Split(',');switch($v[0]){'event'{$p.events[($v[1..3]-join '/')]=@{calls=[long]$v[4];cycles=[double]$v[6];failures=[long]$v[7]}}'objects'{$p.objects[($v[1..2]-join '/')]=@{nodes=[long]$v[3];segments=[long]$v[4];deleted=[long]$v[5]}}'sizes'{$p.sizes=@{node=[int]$v[4];block=[int]$v[6];segment=[int]$v[8];queue=[int]$v[10];slots=[int]$v[12]}}'timer_pair_cycles'{$p.timer=[double]$v[1]}}};return $p}
$b=Profile "$root\results\profile-before-small.csv";$a=Profile "$root\results\profile-after-small.csv"
$cost=@('| 8B · 4P1C 분리 계측 | 이전 | 최종 |','|---|---:|---:|')
foreach($m in @(@('할당 호출 수','0','calls'),@('원소 노드 개별 해제 수','8','calls'),@('첫 hazard 보호 호출 수','2','calls'),@('두 번째 hazard 발행 수','3','calls'),@('원소 공개 CAS 재시도','4','failures'),@('할당 scope 평균 cycles','0','cycles'),@('공개 CAS scope 평균 cycles','4','cycles'),@('제거 scope 평균 cycles','5','cycles'),@('원소 퇴역 CAS 호출 수','6','calls'),@('등록/조회 scope 평균 cycles','1','cycles'),@('첫 hazard scope 평균 cycles','2','cycles'),@('회수 1회 scope 평균 cycles','7','cycles'))){$key='4/1/'+$m[1];$f=if($m[2] -eq 'cycles'){'F2'}else{'F0'};$cost += '| '+$m[0]+' | '+([double]$b.events[$key][$m[2]]).ToString($f)+' | '+([double]$a.events[$key][$m[2]]).ToString($f)+' |'}
$mem=@('| 8B 계측 부하 | 할당한 값 슬롯 수 | 세그먼트 생성 / 해제 | 종료 직전 요청 메모리 |','|---|---:|---|---:|')
foreach($shape in @('1/1','4/1','4/4')){$o=$a.objects[$shape];$bytes=($o.nodes/$a.sizes.slots)*$a.sizes.block+(1+$o.segments-$o.deleted)*$a.sizes.segment+$a.sizes.queue;$mem += '| '+$shape+' | '+$o.nodes+' | '+$o.segments+' / '+$o.deleted+' | '+([long]$bytes)+' B |'}
$template=Get-Content "$root\templates\QueueOptimizationReport.md" -Raw
$report=$template.Replace('{{gate}}',$gate).Replace('{{table}}',($table -join "`n")).Replace('{{cost}}',($cost -join "`n")).Replace('{{memory}}',($mem -join "`n")).Replace('{{timer_before}}',$b.timer.ToString('F2')).Replace('{{timer_after}}',$a.timer.ToString('F2')).Replace('{{block_slots}}',[string]$a.sizes.slots).Replace('{{node_bytes}}',[string]$a.sizes.node).Replace('{{block_bytes}}',[string]$a.sizes.block).Replace('{{segment_bytes}}',[string]$a.sizes.segment).Replace('{{queue_bytes}}',[string]$a.sizes.queue)
$report|Set-Content -Encoding utf8 "$root\results\OPTIMIZATION_REPORT.md"
$report|Set-Content -Encoding utf8 (Join-Path (Split-Path $root) 'CreatorEngine\docs\analysis\LockFreeQueueOptimization20261025.md')
$summary|Format-Table key,before_ns,after_ns,ppl_ns,ratio,max_ratio,lifecycle_ratio,lifecycle_max
Write-Output "GATE=$gate"
